<?php
declare(strict_types=1);
if(session_status()!==PHP_SESSION_ACTIVE)session_start();
require_once __DIR__.'/../lib/storage.php';
require_once __DIR__.'/../lib/testimonials.php';
require_once __DIR__.'/../lib/admin-users.php';
ferrn_require_admin_permission('testimonials');
if(!empty(ferrn_current_admin()['must_change'])){header('Location:/admin/account.php?first=1');exit;}
function t_csrf():string{if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));return (string)$_SESSION['csrf'];}
function t_valid():void{if(!hash_equals((string)($_SESSION['csrf']??''),(string)($_POST['csrf']??''))){http_response_code(403);exit('Invalid request');}}
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
  t_valid();$action=(string)($_POST['action']??'');$items=ferrn_testimonials();
  if($action==='save'){
    $id=trim((string)($_POST['id']??''));$name=trim((string)($_POST['name']??''));$role=trim((string)($_POST['role']??''));$image=trim((string)($_POST['image']??''));$audio=trim((string)($_POST['audio']??''));$sort=(int)($_POST['sort']??999);
    if($name===''||!filter_var($image,FILTER_VALIDATE_URL)||!filter_var($audio,FILTER_VALIDATE_URL)){$error='Name, valid image URL and valid audio URL are required.';}
    else{
      if($id==='')$id=ferrn_slugify($name.'-'.bin2hex(random_bytes(2)));
      $entry=['id'=>$id,'name'=>$name,'role'=>$role,'image'=>$image,'audio'=>$audio,'active'=>!empty($_POST['active']),'sort'=>$sort];
      $found=false;foreach($items as &$t){if(($t['id']??'')===$id){$t=$entry;$found=true;break;}}unset($t);if(!$found)$items[]=$entry;
      if(!ferrn_save_testimonials($items)){$error='Could not save testimonial.';}else{header('Location:/admin/?tab=testimonials');exit;}
    }
  }
  if($action==='toggle'){
    $id=(string)($_POST['id']??'');$found=false;
    foreach($items as &$item){if(($item['id']??'')===$id){$item['active']=empty($item['active']);$found=true;break;}}unset($item);
    if(!$found){$error='Testimonial not found.';}elseif(!ferrn_save_testimonials($items)){$error='Could not update testimonial visibility.';}else{header('Location:/admin/?tab=testimonials');exit;}
  }
  if($action==='delete'){$id=(string)($_POST['id']??'');if(!ferrn_save_testimonials(array_values(array_filter($items,fn($t)=>($t['id']??'')!==$id)))){$error='Could not remove testimonial.';}else{header('Location:/admin/?tab=testimonials');exit;}}
}
$items=ferrn_testimonials();$visible=count(array_filter($items,fn($t)=>!empty($t['active'])));$edit=null;if(!empty($_GET['edit']))foreach($items as $t)if(($t['id']??'')===$_GET['edit']){$edit=$t;break;}
?><!doctype html><html lang="en" data-admin-theme="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Testimonials — Ferrn Admin</title><link rel="icon" href="/assets/ferrn-mark.svg"><link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600&display=swap" rel="stylesheet"><link rel="stylesheet" href="/assets/admin-unified.css?v=20261005-3"><script src="/assets/admin-unified.js?v=20261005-3" defer></script><style>
*{box-sizing:border-box}body{margin:0;font-family:Poppins,Arial}.wrap{width:100%;max-width:none;margin:0}.head{display:flex;justify-content:space-between;gap:20px;align-items:end;margin-bottom:22px}.head h1{font-size:38px;margin:0}.muted{color:var(--adm-muted);font-size:12px}.summary{display:flex;gap:9px;flex-wrap:wrap}.summary span{padding:8px 11px;border:1px solid var(--adm-border);border-radius:999px;font-size:10px}.grid{display:grid;grid-template-columns:minmax(300px,400px) minmax(0,1fr);gap:18px;align-items:start}.panel{border:1px solid var(--adm-border);border-radius:18px;padding:22px}.panel h2{margin:0 0 16px}.field{display:grid;gap:6px;margin-top:12px}.field label{font-size:10px;color:var(--adm-muted)}.field input{width:100%;background:var(--adm-field);border:1px solid var(--adm-border);border-radius:10px;padding:12px;color:var(--adm-text)}.check{display:flex;gap:8px;align-items:center;font-size:12px;color:var(--adm-muted);margin-top:14px}.btn{border:0;border-radius:99px;background:#ff4100;color:#fff;padding:11px 15px;font-weight:600;font-size:11px;cursor:pointer;text-decoration:none;display:inline-flex}.btn.secondary{background:var(--adm-hover);border:1px solid var(--adm-border)}.btn.danger{background:transparent;color:var(--adm-danger);border:1px solid var(--adm-border)}.actions{display:flex;gap:7px;flex-wrap:wrap}.list{display:grid;gap:10px}.item{display:grid;grid-template-columns:74px minmax(0,1fr) auto;gap:15px;align-items:center;padding:14px;border:1px solid var(--adm-border);border-radius:14px;background:var(--adm-field)}.item.hidden-item{opacity:.62}.item img{width:74px;height:74px;object-fit:cover;border-radius:12px}.item strong,.item span{display:block}.item .role{color:var(--adm-muted);font-size:11px;margin:4px 0 8px}.error{padding:12px;background:#35130c;color:#ffa088;border-radius:10px;margin-bottom:12px}@media(max-width:1050px){.grid{grid-template-columns:1fr}.item{grid-template-columns:70px minmax(0,1fr)}.item .actions{grid-column:1/-1}}@media(max-width:560px){.head{display:block}.summary{margin-top:14px}.item{grid-template-columns:55px minmax(0,1fr)}.item img{width:55px;height:55px}}
</style></head><body><div class="app"><?php $tab='testimonials';include __DIR__.'/sidebar.php'; ?><main class="main wrap"><div class="head"><div><div class="muted">FERRN DIGITAL AGENCY</div><h1>Testimonials</h1></div><div class="summary"><span><?=$visible?> visible</span><span><?=count($items)-$visible?> hidden</span><span><?=count($items)?> total</span></div></div><?php if($error):?><div class="error"><?=htmlspecialchars($error)?></div><?php endif;?><div class="grid"><section class="panel"><h2><?=$edit?'Edit testimonial':'Add testimonial'?></h2><p class="muted">Visibility changes update the public testimonial slider automatically.</p><form method="post" action="/admin/testimonials.php"><input type="hidden" name="csrf" value="<?=t_csrf()?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=htmlspecialchars($edit['id']??'')?>"><div class="field"><label>Name</label><input name="name" value="<?=htmlspecialchars($edit['name']??'')?>" required></div><div class="field"><label>Role / company</label><input name="role" value="<?=htmlspecialchars($edit['role']??'')?>"></div><div class="field"><label>Image URL</label><input name="image" type="url" value="<?=htmlspecialchars($edit['image']??'')?>" placeholder="https://..." required></div><div class="field"><label>Audio URL</label><input name="audio" type="url" value="<?=htmlspecialchars($edit['audio']??'')?>" placeholder="https://...mp3" required></div><div class="field"><label>Order</label><input name="sort" type="number" min="1" value="<?=htmlspecialchars((string)($edit['sort']??(count($items)+1)))?>"></div><label class="check"><input type="checkbox" name="active" value="1" <?=!isset($edit['active'])||!empty($edit['active'])?'checked':''?>> Show on website</label><div class="actions" style="margin-top:18px"><button class="btn">Save testimonial</button><?php if($edit):?><a class="btn secondary" href="/admin/?tab=testimonials">Cancel</a><?php endif;?></div></form></section><section class="panel"><h2>Current testimonials</h2><div class="list"><?php foreach($items as $t):$active=!empty($t['active']);?><article class="item <?=$active?'':'hidden-item'?>"><img src="<?=htmlspecialchars($t['image']??'')?>" alt=""><div><strong><?=htmlspecialchars($t['name']??'')?></strong><span class="role"><?=htmlspecialchars($t['role']??'')?></span><span class="status-pill <?=$active?'is-active':'is-disabled'?>"><?=$active?'Visible on site':'Hidden from site'?></span><span class="muted" style="margin-top:7px">Order <?=htmlspecialchars((string)($t['sort']??''))?></span></div><div class="actions"><a class="btn secondary" href="/admin/?tab=testimonials&amp;edit=<?=urlencode((string)($t['id']??''))?>">Edit</a><form method="post" action="/admin/testimonials.php"><input type="hidden" name="csrf" value="<?=t_csrf()?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=htmlspecialchars($t['id']??'')?>"><button class="btn secondary"><?=$active?'Hide on site':'Show on site'?></button></form><form method="post" action="/admin/testimonials.php" onsubmit="return confirm('Remove this testimonial?')"><input type="hidden" name="csrf" value="<?=t_csrf()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=htmlspecialchars($t['id']??'')?>"><button class="btn danger">Remove</button></form></div></article><?php endforeach;?></div></section></div></main></div></body></html>
